using DCWallet.Core;
using Nethereum.RPC.Eth.DTOs;
using Newtonsoft.Json;
using Xunit;
namespace DCWallet.Tests;
public sealed class CurrentTokenCreationReceiptTests
{
    // Captured from actual local Decimal-bytecode fork creation; addresses replaced with public fixtures.
    private const string Fixture = """{"status": "0x1", "logs": [{"address": "0x3333333333333333333333333333333333333333", "data": "", "topics": ["0xe17428da190a3db2fb16175ba372d6b241e61e2249e96a18ddac56ed4336aa19"]}]}""";
    private static TransactionReceipt Receipt()=>JsonConvert.DeserializeObject<TransactionReceipt>(Fixture)!;
    const string Center="0x3333333333333333333333333333333333333333",Creator="0x1111111111111111111111111111111111111111";
    [Fact]public void ActualTupleEventDecodesMetadataAndExpectedCreator(){var item=Assert.Single(CurrentTokenCreationReceiptReader.Read(Receipt(),Center,Creator));Assert.Equal("0x2222222222222222222222222222222222222222",item.Address);Assert.Equal(Creator,item.Creator);Assert.Equal("dcqafork",item.Symbol);Assert.False(item.IsReserveless);}
    [Fact]public void WrongCreatorEmitterOrFailedReceiptNeverReturnFalseAddress(){Assert.Throws<InvalidOperationException>(()=>CurrentTokenCreationReceiptReader.Read(Receipt(),Center,Center));Assert.Throws<InvalidOperationException>(()=>CurrentTokenCreationReceiptReader.Read(Receipt(),Creator));var receipt=Receipt();receipt.Status=new Nethereum.Hex.HexTypes.HexBigInteger(0);Assert.Throws<InvalidOperationException>(()=>CurrentTokenCreationReceiptReader.Read(receipt,Center));}
    [Fact]public void LegacyAddressOnlyEventRemainsSupportedWithoutUnprovedCreatorClaim(){var receipt=JsonConvert.DeserializeObject<TransactionReceipt>("""{"status":"0x1","logs":[{"address":"0x3333333333333333333333333333333333333333","data":"0x0000000000000000000000002222222222222222222222222222222222222222","topics":["0x" ]}]}""")!;receipt.Logs[0].Topics[0]="0x"+Nethereum.Util.Sha3Keccack.Current.CalculateHash("TokenDeployed(address)");var token=Assert.Single(CurrentTokenCreationReceiptReader.Read(receipt,Center));Assert.Null(token.Creator);Assert.Throws<InvalidOperationException>(()=>CurrentTokenCreationReceiptReader.Read(receipt,Center,Creator));}
}
